'use strict';

// level: ['CSP'] = CSP only, ['CSP','CR'] = both levels, ['CR'] = CR only
// answer: zero-based index of correct option
const QUESTIONS = [
  // ─── TOPIC 1 : Principes et valeurs de la République ───────────────────────
  { id:'q001', level:['CSP','CR'], topic:1, q:'Quelle est la devise de la République française ?', options:['Travail, famille, patrie','Liberté, égalité, fraternité','Unité, diversité, progrès','Laïcité, égalité, solidarité'], answer:1, explanation:'La devise "Liberté, Égalité, Fraternité" est inscrite dans la Constitution de 1958 et figure sur les bâtiments publics et documents officiels.' },
  { id:'q002', level:['CSP','CR'], topic:1, q:'Quelles sont les couleurs du drapeau français ?', options:['Rouge, blanc et vert','Bleu, jaune et rouge','Bleu, blanc et rouge','Blanc, rouge et noir'], answer:2, explanation:'Le drapeau tricolore bleu, blanc, rouge est le symbole officiel de la France depuis la Révolution française.' },
  { id:'q003', level:['CSP','CR'], topic:1, q:'Qu\'est-ce que la Marseillaise ?', options:['Une danse traditionnelle','Un plat typique de Marseille','L\'hymne national de la France','Une marche militaire sans statut officiel'], answer:2, explanation:'La Marseillaise est l\'hymne national de la France, composée en 1792 lors de la Révolution française.' },
  { id:'q004', level:['CSP','CR'], topic:1, q:'Qui est Marianne ?', options:['Une reine de France','La patronne de Paris','Une figure historique de la résistance','Le symbole de la République française'], answer:3, explanation:'Marianne est le symbole de la République française. Elle représente la liberté et la raison et figure sur les timbres, pièces et dans les mairies.' },
  { id:'q005', level:['CSP','CR'], topic:1, q:'Quel animal est un symbole de la France ?', options:['L\'aigle','Le lion','Le loup','Le coq gaulois'], answer:3, explanation:'Le coq gaulois est un symbole emblématique de la France, utilisé notamment dans le sport.' },
  { id:'q006', level:['CSP','CR'], topic:1, q:'"La France est une République indivisible, ..., démocratique et sociale". Complétez cette phrase extraite de l\'article 1er de la Constitution :', options:['religieuse','fédérale','laïque','monarchique'], answer:2, explanation:'L\'article 1er de la Constitution dispose que "La France est une République indivisible, laïque, démocratique et sociale."' },
  { id:'q007', level:['CSP','CR'], topic:1, q:'En quelle année la loi de séparation des Églises et de l\'État a-t-elle été votée ?', options:['1789','1945','1958','1905'], answer:3, explanation:'La loi de séparation des Églises et de l\'État a été votée le 9 décembre 1905. Elle est le fondement de la laïcité française.' },
  { id:'q008', level:['CSP','CR'], topic:1, q:'Qu\'est-ce que la laïcité ?', options:['L\'obligation de pratiquer une religion','L\'interdiction de toute pratique religieuse','La religion officielle de la France','La séparation des Églises et de l\'État garantissant la liberté de conscience'], answer:3, explanation:'La laïcité sépare les institutions publiques de toute religion et garantit la liberté de conscience et de culte pour tous.' },
  { id:'q009', level:['CSP','CR'], topic:1, q:'Pourquoi le principe de laïcité doit-il être respecté à l\'école ?', options:['Pour que les élèves soient mieux notés','Pour interdire toute culture étrangère','Pour que l\'école soit un lieu neutre où tous les élèves sont égaux','Pour que les enseignants puissent pratiquer leur religion'], answer:2, explanation:'L\'école publique est un espace de neutralité religieuse garantissant l\'égalité de tous les élèves, quelle que soit leur croyance.' },
  { id:'q010', level:['CSP','CR'], topic:1, q:'Une personne a-t-elle le droit de ne pas croire en une religion ?', options:['Non, la France est un pays catholique','Non, il faut déclarer une religion à l\'état civil','Oui, mais seulement les citoyens français','Oui, la liberté de conscience garantit ce droit'], answer:3, explanation:'La liberté de conscience, garantie par la laïcité, inclut le droit de ne pas avoir de religion.' },
  { id:'q011', level:['CSP','CR'], topic:1, q:'Une personne peut-elle changer librement de religion ?', options:['Non, il faut une autorisation préfectorale','Non, c\'est interdit par la loi','Oui, mais seulement une fois','Oui, la liberté de conscience le permet'], answer:3, explanation:'La liberté de conscience, pilier de la laïcité, inclut le droit de changer de religion librement.' },
  { id:'q012', level:['CSP','CR'], topic:1, q:'Quel est le nom de l\'hymne national français ?', options:['L\'Internationale','Le Chant du Départ','La Carmagnole','La Marseillaise'], answer:3, explanation:'La Marseillaise est l\'hymne national depuis 1795, réadoptée officiellement sous la Ve République.' },
  { id:'q013', level:['CSP','CR'], topic:1, q:'Quelle est la date de la fête nationale française ?', options:['Le 11 novembre','Le 8 mai','Le 1er mai','Le 14 juillet'], answer:3, explanation:'Le 14 juillet célèbre la prise de la Bastille (1789). Un défilé militaire traditionnel est organisé sur les Champs-Élysées.' },
  { id:'q014', level:['CSP','CR'], topic:1, q:'Le régime de la France est :', options:['Une monarchie constitutionnelle','Une dictature militaire','Une théocratie','Une République'], answer:3, explanation:'La France est une République depuis 1792. La Ve République, fondée en 1958, est le régime actuel.' },
  { id:'q015', level:['CSP','CR'], topic:1, q:'Le principe d\'égalité signifie que :', options:['Tout le monde reçoit le même salaire','Tout le monde doit avoir le même niveau de vie','Les Français sont prioritaires sur les étrangers','Tous les citoyens ont les mêmes droits et sont traités de la même façon devant la loi'], answer:3, explanation:'L\'égalité signifie que la loi s\'applique de la même manière à tous, sans discrimination fondée sur l\'origine, le sexe ou la religion.' },
  { id:'q016', level:['CSP','CR'], topic:1, q:'A-t-on le droit d\'insulter publiquement quelqu\'un parce qu\'il est différent (handicap, sexe, apparence…) ?', options:['Oui, c\'est couvert par la liberté d\'expression','Oui, dans les espaces privés','Non, sauf si c\'est une opinion personnelle','Non, c\'est une discrimination punissable par la loi'], answer:3, explanation:'Les insultes discriminatoires constituent une infraction pénale en France, quelle que soit la motivation.' },
  { id:'q017', level:['CSP','CR'], topic:1, q:'Certains métiers peuvent-ils être réservés aux hommes ?', options:['Oui, dans les forces armées','Oui, dans les professions physiquement exigeantes','Non, le principe d\'égalité interdit la discrimination selon le sexe','Oui, dans les professions religieuses'], answer:2, explanation:'Le principe d\'égalité entre femmes et hommes interdit toute discrimination fondée sur le sexe dans l\'accès à l\'emploi.' },
  { id:'q018', level:['CSP','CR'], topic:1, q:'De quand date la Constitution de la Ve République ?', options:['1789','1945','1981','1958'], answer:3, explanation:'La Constitution de la Ve République a été adoptée par référendum le 4 octobre 1958, sous l\'impulsion du général de Gaulle.' },
  { id:'q019', level:['CSP','CR'], topic:1, q:'Quel symbole de la République française est tricolore ?', options:['La Marianne','Le coq gaulois','La tour Eiffel','Le drapeau français'], answer:3, explanation:'Le drapeau tricolore bleu, blanc, rouge est le symbole officiel tricolore de la République française.' },
  { id:'q020', level:['CSP','CR'], topic:1, q:'Où peut-on voir la devise de la République ?', options:['Uniquement dans les musées','Sur les plaques de voiture','Sur les billets de banque','Sur les bâtiments publics et les documents officiels'], answer:3, explanation:'La devise "Liberté, Égalité, Fraternité" est gravée ou affichée sur les mairies, tribunaux et autres édifices publics.' },
  { id:'q021', level:['CSP','CR'], topic:1, q:'Quelle est la langue officielle de la République française ?', options:['L\'occitan','Le breton','L\'alsacien','Le français'], answer:3, explanation:'L\'article 2 de la Constitution dispose que "La langue de la République est le français."' },
  { id:'q022', level:['CSP','CR'], topic:1, q:'Que signifie le mot "fraternité" dans la devise française ?', options:['L\'obligation d\'aimer tous les Français','L\'égalité des revenus','Le respect de la religion','La solidarité et l\'entraide entre les membres de la société'], answer:3, explanation:'La fraternité désigne la solidarité nationale, le soutien mutuel entre citoyens et l\'aide aux plus vulnérables.' },
  { id:'q023', level:['CSP','CR'], topic:1, q:'Que signifie la liberté ?', options:['Le droit de faire tout ce qu\'on veut sans limite','Le droit d\'agir, penser et s\'exprimer librement dans le respect des lois','Un droit réservé aux citoyens français','Le droit de ne pas obéir aux lois injustes'], answer:1, explanation:'La liberté permet d\'agir, penser et s\'exprimer librement, dans les limites fixées par la loi pour protéger les droits d\'autrui.' },
  { id:'q024', level:['CSP','CR'], topic:1, q:'Quel est l\'un des rôles des associations ?', options:['Voter des lois','Remplacer les services publics','Percevoir des impôts','Favoriser la participation citoyenne et l\'entraide sociale'], answer:3, explanation:'Les associations loi 1901 permettent aux citoyens de se regrouper pour agir collectivement dans de nombreux domaines (sport, culture, social…).' },
  { id:'q025', level:['CSP','CR'], topic:1, q:'Quelle proposition est correcte concernant la liberté d\'expression ?', options:['Elle permet de dire n\'importe quoi sans limite','Elle s\'applique seulement aux journalistes','Elle est réservée aux citoyens français','Elle permet d\'exprimer ses opinions mais comporte des limites légales'], answer:3, explanation:'La liberté d\'expression est garantie mais limitée : l\'incitation à la haine, la diffamation et les appels à la violence sont punis par la loi.' },
  { id:'q026', level:['CSP','CR'], topic:1, q:'Qu\'est-ce qui est traditionnellement organisé sur les Champs-Élysées le 14 juillet ?', options:['Un concert de musique classique','Une course automobile','Un marché artisanal','Un défilé militaire'], answer:3, explanation:'Le défilé militaire du 14 juillet sur les Champs-Élysées est une tradition républicaine qui commémore la fête nationale.' },
  { id:'q027', level:['CSP','CR'], topic:1, q:'Un enfant peut-il refuser d\'aller à l\'école pour une raison religieuse ?', options:['Oui, si ses parents le souhaitent','Oui, lors des fêtes religieuses','Oui, avec l\'accord du directeur','Non, l\'instruction est obligatoire et la laïcité s\'applique'], answer:3, explanation:'L\'instruction est obligatoire de 3 à 16 ans. La laïcité s\'applique à l\'école publique et une raison religieuse ne dispense pas de cette obligation.' },
  { id:'q028', level:['CSP','CR'], topic:1, q:'Quel droit est garanti par la laïcité ?', options:['Le droit de vote','Le droit au travail','La liberté de circulation','La liberté de conscience et de religion'], answer:3, explanation:'La laïcité garantit la liberté de conscience, c\'est-à-dire le droit de croire ou non, et de pratiquer la religion de son choix.' },
  { id:'q029', level:['CSP','CR'], topic:1, q:'Quels sont des symboles officiels de la République française ?', options:['Le château de Versailles et la tour Eiffel','La croix et la fleur de lys','La Corse et la Bretagne','Le drapeau tricolore, la Marseillaise et Marianne'], answer:3, explanation:'Les symboles officiels de la République incluent le drapeau tricolore, la Marseillaise, Marianne, la devise et le 14 juillet.' },
  { id:'q030', level:['CSP','CR'], topic:1, q:'Qu\'est-ce que l\'égalité ?', options:['Le fait que tous gagnent le même salaire','Un principe qui avantage les plus défavorisés','Un droit réservé aux citoyens français','Le traitement identique de tous devant la loi, sans discrimination'], answer:3, explanation:'L\'égalité républicaine signifie que la loi s\'applique de manière identique à chaque personne, sans distinction d\'origine, de sexe ou de religion.' },

  // ─── TOPIC 2 : Système institutionnel et politique ──────────────────────────
  { id:'q031', level:['CSP','CR'], topic:2, q:'Qui nomme le Premier ministre ?', options:['Le Parlement','Le Sénat','L\'Assemblée nationale','Le président de la République'], answer:3, explanation:'En vertu de l\'article 8 de la Constitution, le Premier ministre est nommé par le président de la République.' },
  { id:'q032', level:['CSP','CR'], topic:2, q:'Le Parlement est composé :', options:['Du président de la République et du gouvernement','Des maires et des préfets','Du Conseil d\'État et de la Cour des comptes','De l\'Assemblée nationale et du Sénat'], answer:3, explanation:'Le Parlement français est bicaméral : il comprend l\'Assemblée nationale (577 députés) et le Sénat (348 sénateurs).' },
  { id:'q033', level:['CSP','CR'], topic:2, q:'À partir de quel âge a-t-on le droit de voter ?', options:['16 ans','21 ans','25 ans','18 ans'], answer:3, explanation:'Le droit de vote est accordé à tous les citoyens français dès l\'âge de 18 ans, sous réserve d\'inscription sur les listes électorales.' },
  { id:'q034', level:['CSP','CR'], topic:2, q:'Pour combien de temps est élu le président de la République française ?', options:['4 ans','6 ans','7 ans','5 ans'], answer:3, explanation:'Depuis la révision constitutionnelle de 2000, le mandat présidentiel est de 5 ans (quinquennat), renouvelable une fois.' },
  { id:'q035', level:['CSP','CR'], topic:2, q:'Qui est élu lors des élections législatives ?', options:['Le président de la République','Les sénateurs','Les maires','Les députés'], answer:3, explanation:'Les élections législatives permettent d\'élire les 577 membres de l\'Assemblée nationale pour un mandat de 5 ans.' },
  { id:'q036', level:['CSP','CR'], topic:2, q:'Combien de députés composent l\'Assemblée nationale ?', options:['348','600','450','577'], answer:3, explanation:'L\'Assemblée nationale est composée de 577 députés élus au scrutin uninominal majoritaire à deux tours.' },
  { id:'q037', level:['CSP','CR'], topic:2, q:'Qui réside au palais de l\'Élysée ?', options:['Le Premier ministre','Le président du Sénat','Le président de l\'Assemblée nationale','Le président de la République'], answer:3, explanation:'Le palais de l\'Élysée, situé dans le 8e arrondissement de Paris, est la résidence officielle du président de la République.' },
  { id:'q038', level:['CSP','CR'], topic:2, q:'Qui vote les lois ?', options:['Le président de la République','Le gouvernement','Le Conseil constitutionnel','Le Parlement'], answer:3, explanation:'Le pouvoir législatif appartient au Parlement (Assemblée nationale et Sénat), qui vote et adopte les lois.' },
  { id:'q039', level:['CSP','CR'], topic:2, q:'La séparation des pouvoirs est un principe fondamental. Quels sont les trois pouvoirs concernés ?', options:['Pouvoir central, régional, local','Pouvoir militaire, civil, religieux','Pouvoir présidentiel, parlementaire, médiatique','Pouvoir législatif, exécutif, judiciaire'], answer:3, explanation:'La théorie de Montesquieu sépare : le législatif (voter les lois), l\'exécutif (gouverner) et le judiciaire (rendre la justice).' },
  { id:'q040', level:['CSP','CR'], topic:2, q:'Qui sanctionne l\'auteur d\'un vol ?', options:['Le préfet','Le maire','Le parlement','Le juge'], answer:3, explanation:'Le pouvoir judiciaire, incarné par les juges, est chargé de sanctionner les infractions à la loi, y compris le vol.' },
  { id:'q041', level:['CSP','CR'], topic:2, q:'Pour combien de temps sont élus les sénateurs ?', options:['4 ans','5 ans','7 ans','6 ans'], answer:3, explanation:'Les sénateurs sont élus pour 6 ans au suffrage indirect (par des grands électeurs) et renouvelés par moitié tous les 3 ans.' },
  { id:'q042', level:['CSP','CR'], topic:2, q:'Pour combien de temps sont élus les députés ?', options:['4 ans','6 ans','7 ans','5 ans'], answer:3, explanation:'Les députés de l\'Assemblée nationale sont élus pour un mandat de 5 ans lors des élections législatives.' },
  { id:'q043', level:['CSP','CR'], topic:2, q:'Quelle condition est nécessaire pour voter aux élections ?', options:['Payer ses impôts','Avoir un emploi','Parler couramment le français','Être inscrit sur les listes électorales'], answer:3, explanation:'Pour voter, il faut être citoyen français, avoir 18 ans et être inscrit sur les listes électorales de sa commune.' },
  { id:'q044', level:['CSP','CR'], topic:2, q:'Qui peut voter aux élections en France ?', options:['Toute personne résidant en France','Seulement les Français de naissance','Toute personne ayant un titre de séjour','Les citoyens français (et européens pour certaines élections locales et européennes)'], answer:3, explanation:'Seuls les citoyens français peuvent voter aux élections nationales. Les ressortissants européens peuvent voter aux élections locales et européennes.' },
  { id:'q045', level:['CSP','CR'], topic:2, q:'Que signifie le suffrage universel ?', options:['Seuls les hommes ont le droit de voter','Seuls les propriétaires votent','Les élus votent à la place des citoyens','Tous les citoyens majeurs ont le droit de voter'], answer:3, explanation:'Le suffrage universel, instauré pour les hommes en 1848 et pour les femmes en 1944, donne le droit de vote à tout citoyen majeur.' },
  { id:'q046', level:['CSP','CR'], topic:2, q:'Combien y a-t-il de départements en France ?', options:['96','22','13','101'], answer:3, explanation:'La France compte 101 départements : 96 métropolitains et 5 d\'outre-mer (Guadeloupe, Martinique, Guyane, Réunion, Mayotte).' },
  { id:'q047', level:['CSP','CR'], topic:2, q:'Qui représente l\'État dans un département ?', options:['Le maire','Le président du conseil départemental','Le député','Le préfet'], answer:3, explanation:'Le préfet est le représentant de l\'État dans le département. Il veille à l\'application des lois et règlements.' },
  { id:'q048', level:['CSP','CR'], topic:2, q:'Qui dirige la commune ?', options:['Le préfet','Le député','Le président du conseil régional','Le maire'], answer:3, explanation:'Le maire est élu par le conseil municipal et dirige l\'administration communale.' },
  { id:'q049', level:['CSP','CR'], topic:2, q:'Quel est le régime politique de la France aujourd\'hui ?', options:['Une monarchie constitutionnelle','La IVe République','Un régime présidentiel pur','La Ve République'], answer:3, explanation:'La Ve République, fondée en 1958 par le général de Gaulle, est le régime politique actuel de la France.' },
  { id:'q050', level:['CSP','CR'], topic:2, q:'Quel est le rôle des députés ?', options:['Nommer les ministres','Juger les criminels','Gérer les communes','Voter les lois et contrôler le gouvernement'], answer:3, explanation:'Les députés représentent les citoyens au Parlement, votent les lois et peuvent mettre en cause la responsabilité du gouvernement.' },
  { id:'q051', level:['CSP','CR'], topic:2, q:'Combien d\'États font partie de l\'Union européenne au 1er janvier 2025 ?', options:['25','28','30','27'], answer:3, explanation:'L\'Union européenne compte 27 États membres depuis le Brexit (départ du Royaume-Uni en 2020).' },
  { id:'q052', level:['CSP','CR'], topic:2, q:'Quelle est la monnaie utilisée en France ?', options:['Le franc','La livre sterling','Le mark','L\'euro'], answer:3, explanation:'La France a adopté l\'euro comme monnaie unique en 2002, lors du passage aux pièces et billets en euros.' },
  { id:'q053', level:['CSP','CR'], topic:2, q:'Quand célèbre-t-on la journée de l\'Europe ?', options:['Le 1er janvier','Le 25 mars','Le 14 juillet','Le 9 mai'], answer:3, explanation:'Le 9 mai est la Journée de l\'Europe, commémorant la déclaration Schuman de 1950, qui proposa la construction européenne.' },
  { id:'q054', level:['CSP','CR'], topic:2, q:'Quel pays est un pays fondateur de l\'Union européenne ?', options:['La Pologne','La Suède','La Roumanie','La France'], answer:3, explanation:'La France est l\'un des six pays fondateurs de la CEE (1957) : France, Allemagne, Italie, Belgique, Pays-Bas, Luxembourg.' },
  { id:'q055', level:['CSP','CR'], topic:2, q:'Quel est le rôle du Parlement ?', options:['Gouverner le pays','Juger les crimes','Percevoir les impôts','Voter les lois et contrôler l\'action du gouvernement'], answer:3, explanation:'Le Parlement exerce le pouvoir législatif : il vote les lois, approuve le budget et contrôle l\'action du gouvernement.' },
  { id:'q056', level:['CSP','CR'], topic:2, q:'Est-ce que le président de la République a tous les pouvoirs ?', options:['Oui, en tant que chef de l\'État','Oui, lors des périodes de crise','Oui, sur les questions militaires','Non, les pouvoirs sont séparés entre plusieurs institutions'], answer:3, explanation:'Le principe de séparation des pouvoirs s\'applique : le président partage les pouvoirs avec le Parlement, le gouvernement et la justice.' },
  { id:'q057', level:['CSP','CR'], topic:2, q:'Qui est le préfet ?', options:['Le chef de la région','Le maire de la grande ville','Le président du département','Le représentant de l\'État dans le département'], answer:3, explanation:'Nommé par le gouvernement, le préfet représente l\'État dans le département, applique les lois et coordonne les services de l\'État.' },
  { id:'q058', level:['CSP','CR'], topic:2, q:'Quel État n\'est pas membre de l\'Union européenne ?', options:['L\'Espagne','La Belgique','L\'Italie','La Suisse'], answer:3, explanation:'La Suisse n\'est pas membre de l\'UE. Elle est associée par des accords bilatéraux mais reste en dehors de l\'Union.' },
  { id:'q059', level:['CSP','CR'], topic:2, q:'Quelle condition est nécessaire pour voter aux élections européennes ?', options:['Avoir la nationalité française uniquement','Être résident depuis 10 ans','Être majeur et citoyen de l\'UE inscrit sur les listes électorales','Avoir un emploi dans un pays de l\'UE'], answer:2, explanation:'Tout citoyen de l\'Union européenne résidant en France peut voter aux élections européennes, à condition d\'être inscrit sur les listes électorales.' },
  { id:'q060', level:['CSP','CR'], topic:2, q:'Qui élit les députés européens ?', options:['Les gouvernements des États membres','Les chefs d\'État européens','Les maires de l\'UE','Les citoyens de l\'Union européenne'], answer:3, explanation:'Les députés européens sont élus au suffrage universel direct par les citoyens de chaque État membre de l\'UE.' },

  // ─── TOPIC 3 : Droits et devoirs ────────────────────────────────────────────
  { id:'q061', level:['CSP','CR'], topic:3, q:'De quelle année date la Déclaration des droits de l\'homme et du citoyen ?', options:['1815','1848','1958','1789'], answer:3, explanation:'La Déclaration des droits de l\'homme et du citoyen a été adoptée le 26 août 1789, pendant la Révolution française.' },
  { id:'q062', level:['CSP','CR'], topic:3, q:'Lequel de ces droits est un droit fondamental ?', options:['Le droit de conduire','Le droit de partir en vacances','Le droit à une connexion internet','La liberté d\'expression'], answer:3, explanation:'La liberté d\'expression est un droit fondamental garanti par la Constitution et la Déclaration des droits de l\'homme de 1789.' },
  { id:'q063', level:['CSP','CR'], topic:3, q:'La peine de mort est :', options:['Appliquée pour les crimes les plus graves','Suspendue temporairement','Réservée aux terroristes','Abolie en France depuis 1981'], answer:3, explanation:'La peine de mort a été abolie en France par la loi Badinter du 9 octobre 1981, sous le gouvernement de François Mitterrand.' },
  { id:'q064', level:['CSP','CR'], topic:3, q:'En France, est-ce légal d\'être marié à plusieurs personnes en même temps ?', options:['Oui, si toutes les personnes sont consentantes','Oui, selon certaines traditions culturelles','Oui, dans certains départements','Non, la polygamie est interdite par la loi'], answer:3, explanation:'La polygamie est strictement interdite en France par le Code civil. Seul le mariage monogame est reconnu.' },
  { id:'q065', level:['CSP','CR'], topic:3, q:'Une femme peut avorter :', options:['Jamais, l\'avortement est interdit','Seulement en cas de danger pour sa vie','Seulement avec l\'accord du père','Librement, jusqu\'à 14 semaines de grossesse'], answer:3, explanation:'Depuis la loi Veil (1975) et ses révisions, l\'IVG est légale en France jusqu\'à 14 semaines de grossesse.' },
  { id:'q066', level:['CSP','CR'], topic:3, q:'Est-il toujours possible de divorcer ?', options:['Non, le divorce est interdit','Oui, mais seulement après 10 ans de mariage','Oui, seulement si les deux époux sont d\'accord','Oui, la loi française permet le divorce'], answer:3, explanation:'Le divorce est possible en France selon plusieurs procédures, notamment par consentement mutuel ou pour faute.' },
  { id:'q067', level:['CSP','CR'], topic:3, q:'Pourquoi les libertés individuelles peuvent-elles être limitées ?', options:['Pour punir les personnes défavorisées','Pour avantager les citoyens français','Pour des raisons économiques uniquement','Pour protéger l\'ordre public et les droits d\'autrui'], answer:3, explanation:'Aucune liberté n\'est absolue. Elles peuvent être limitées pour protéger l\'ordre public, la sécurité et les droits des autres.' },
  { id:'q068', level:['CSP','CR'], topic:3, q:'Que risque une personne qui ne respecte pas la loi ?', options:['Rien si c\'est la première fois','Une amende uniquement','L\'expulsion du territoire uniquement','Des sanctions pénales (amende, emprisonnement selon la gravité)'], answer:3, explanation:'Toute infraction à la loi expose à des sanctions : contravention (la moins grave), délit et crime (le plus grave) peuvent mener à l\'emprisonnement.' },
  { id:'q069', level:['CSP','CR'], topic:3, q:'Quel est le rôle de la police ?', options:['Voter les lois','Juger les criminels','Percevoir les impôts','Maintenir l\'ordre public et protéger les citoyens'], answer:3, explanation:'La police nationale et la gendarmerie assurent la sécurité des personnes et des biens et veillent au respect des lois.' },
  { id:'q070', level:['CSP','CR'], topic:3, q:'Quelle est l\'infraction la plus grave ?', options:['La contravention','Le délit','L\'avertissement','Le crime'], answer:3, explanation:'Les infractions pénales sont classées par ordre croissant de gravité : contravention, délit, crime. Le crime est la plus grave.' },
  { id:'q071', level:['CSP','CR'], topic:3, q:'Que doit faire une personne en cas d\'accident ?', options:['Partir rapidement','Attendre que d\'autres s\'en occupent','Appeler son avocat avant d\'agir','S\'arrêter, porter secours et appeler les secours'], answer:3, explanation:'Ne pas porter secours à une personne en danger est un délit en France (non-assistance à personne en danger).' },
  { id:'q072', level:['CSP','CR'], topic:3, q:'Jeter une bouteille dans la rue est :', options:['Autorisé si on ne trouve pas de poubelle','Autorisé dans certaines zones','Autorisé dans les parcs uniquement','Une incivilité et une infraction à la loi'], answer:3, explanation:'Jeter des déchets dans l\'espace public est une contravention passible d\'amende en France.' },
  { id:'q073', level:['CSP','CR'], topic:3, q:'Quel est le rôle de la gendarmerie ?', options:['Défendre les frontières militaires','Gérer les prisons','Contrôler les finances publiques','Assurer la sécurité publique, notamment en zone rurale'], answer:3, explanation:'La gendarmerie nationale, corps militaire, assure la sécurité publique principalement dans les zones rurales et périurbaines.' },
  { id:'q074', level:['CSP','CR'], topic:3, q:'Qu\'est-ce qu\'une infraction ?', options:['Une opinion contraire à la loi','Une demande administrative refusée','Un désaccord entre citoyens','Un acte illégal puni par la loi'], answer:3, explanation:'Une infraction est tout acte interdit par la loi et passible d\'une sanction pénale (contravention, délit ou crime).' },
  { id:'q075', level:['CSP','CR'], topic:3, q:'Que doit faire une victime de violences ?', options:['Se venger elle-même','Ne rien dire pour éviter des complications','Régler cela en famille uniquement','Porter plainte auprès de la police ou de la gendarmerie'], answer:3, explanation:'Les victimes de violences doivent porter plainte auprès des forces de l\'ordre ou contacter des associations d\'aide aux victimes.' },
  { id:'q076', level:['CSP','CR'], topic:3, q:'Comment peut-on réduire ses déchets ?', options:['En les brûlant dans son jardin','En les enterrant','En les jetant dans les égouts','En triant, réutilisant et réduisant sa consommation'], answer:3, explanation:'La réduction des déchets passe par le tri sélectif, la réutilisation des objets et la limitation des achats superflus.' },
  { id:'q077', level:['CSP','CR'], topic:3, q:'Parmi ces textes, lequel garantit les droits et libertés en France ?', options:['Le Code du travail','Le Traité de Maastricht','Le Code civil','La Constitution de 1958'], answer:3, explanation:'La Constitution de 1958 garantit les droits et libertés fondamentaux, en incluant la Déclaration de 1789 et le préambule de 1946.' },
  { id:'q078', level:['CSP','CR'], topic:3, q:'Déposer une machine à laver cassée sur le trottoir est :', options:['Autorisé si on prévient la mairie','Autorisé les jours de collecte uniquement','Autorisé si l\'appareil est propre','Un acte d\'incivilité et une infraction'], answer:3, explanation:'Déposer des encombrants sur la voie publique hors des créneaux de collecte est une infraction passible d\'amende.' },
  { id:'q079', level:['CSP','CR'], topic:3, q:'Que permet la citoyenneté française ?', options:['De ne pas payer d\'impôts','De voyager sans visa uniquement','D\'avoir automatiquement tous les droits sociaux','De voter, d\'être élu, d\'accéder à certains emplois publics'], answer:3, explanation:'La citoyenneté française confère le droit de vote, l\'éligibilité aux fonctions publiques et l\'accès à certains emplois de la fonction publique.' },
  { id:'q080', level:['CSP','CR'], topic:3, q:'Quelle liberté permet à une personne de ne pas avoir de religion ?', options:['La liberté d\'expression','La liberté d\'association','La liberté de circulation','La liberté de conscience et de religion'], answer:3, explanation:'La liberté de conscience, garantie par la laïcité, inclut le droit de ne professer aucune religion (athéisme, agnosticisme).' },
  { id:'q081', level:['CSP','CR'], topic:3, q:'Qu\'est-ce que la liberté d\'expression ?', options:['Le droit de dire n\'importe quoi','Le droit de critiquer le gouvernement sans aucune limite','Le droit de publier sans payer de taxes','Le droit d\'exprimer ses opinions dans le respect des lois'], answer:3, explanation:'La liberté d\'expression protège le droit d\'exprimer toute opinion, sauf celles incitant à la haine, à la violence ou portant atteinte à la dignité.' },
  { id:'q082', level:['CSP','CR'], topic:3, q:'Quel droit permet à une personne de se défendre devant la justice ?', options:['Le droit de grève','Le droit d\'asile','Le droit de pétition','Le droit à la défense et à un procès équitable'], answer:3, explanation:'Toute personne poursuivie pénalement a droit à un avocat, à un procès équitable et à la présomption d\'innocence.' },
  { id:'q083', level:['CSP','CR'], topic:3, q:'Quel texte a été adopté pendant la Révolution française ?', options:['La Constitution de la Ve République','Le Code Napoléon','La Charte de l\'environnement','La Déclaration des droits de l\'homme et du citoyen'], answer:3, explanation:'La Déclaration des droits de l\'homme et du citoyen a été adoptée le 26 août 1789 par l\'Assemblée nationale constituante.' },
  { id:'q084', level:['CSP','CR'], topic:3, q:'En quoi consiste la traite des êtres humains ?', options:['Le commerce légal de produits exotiques','Le trafic d\'animaux','L\'immigration clandestine','L\'exploitation de personnes à des fins d\'esclavage, de prostitution ou de travail forcé'], answer:3, explanation:'La traite des êtres humains est un crime grave qui consiste à exploiter des personnes par la contrainte ou la tromperie.' },
  { id:'q085', level:['CSP','CR'], topic:3, q:'Comment s\'appelle la Constitution actuelle de la France ?', options:['La Constitution de 1789','La Déclaration des droits de l\'homme','Le Code civil','La Constitution de la Ve République'], answer:3, explanation:'La Constitution de la Ve République, adoptée le 4 octobre 1958, est la loi fondamentale qui régit l\'organisation politique de la France.' },
  { id:'q086', level:['CSP','CR'], topic:3, q:'Faut-il réduire ses déchets ?', options:['Non, les services de collecte s\'en chargent','Non, cela ne change rien','Oui, mais seulement les entreprises y sont obligées','Oui, c\'est un devoir civique pour protéger l\'environnement'], answer:3, explanation:'La réduction des déchets est une responsabilité individuelle et collective inscrite dans la Charte de l\'environnement.' },
  { id:'q087', level:['CSP','CR'], topic:3, q:'Concernant les droits individuels, quelle proposition est correcte ?', options:['Les droits individuels sont réservés aux Français','Les droits individuels n\'existent pas en France','Les droits individuels sont absolus et ne peuvent être limités','Les droits individuels peuvent être limités pour protéger l\'ordre public'], answer:3, explanation:'Les droits individuels peuvent être restreints par la loi pour protéger l\'ordre public, la sécurité et les droits d\'autrui.' },
  { id:'q088', level:['CSP','CR'], topic:3, q:'Quel est le texte fondateur établissant en France les droits et devoirs de chaque citoyen ?', options:['Le Code Napoléon de 1804','La Constitution de la IIIe République','L\'Ordonnance de Villers-Cotterêts','La Déclaration des droits de l\'homme et du citoyen de 1789'], answer:3, explanation:'La DDHC de 1789 est le texte fondateur des droits et libertés. Elle est intégrée au bloc de constitutionnalité.' },
  { id:'q089', level:['CSP','CR'], topic:3, q:'Que doit-on faire face aux ordres des forces de l\'ordre ?', options:['Les ignorer si on pense avoir raison','S\'y conformer dans le cadre légal et contester devant un tribunal si nécessaire','Les refuser toujours','Les accepter uniquement si on est coupable'], answer:1, explanation:'On doit se conformer aux ordres légaux des forces de l\'ordre. Toute contestation doit être faite par voie légale.' },
  { id:'q090', level:['CSP','CR'], topic:3, q:'Quelle obligation concerne toutes les personnes résidant en France quelle que soit leur nationalité ?', options:['L\'obligation de voter','L\'obligation d\'apprendre le français','L\'obligation de payer des impôts dès la première semaine','L\'obligation de respecter les lois françaises'], answer:3, explanation:'Toute personne présente sur le territoire français est soumise aux lois françaises, quelle que soit sa nationalité.' },

  // ─── TOPIC 4 : Histoire, géographie et culture ──────────────────────────────
  { id:'q091', level:['CSP','CR'], topic:4, q:'En quelle année a débuté la Révolution française ?', options:['1776','1793','1799','1789'], answer:3, explanation:'La Révolution française débute le 14 juillet 1789 avec la prise de la Bastille, symbole de la fin de l\'absolutisme.' },
  { id:'q092', level:['CSP','CR'], topic:4, q:'Qui était Napoléon Ier ?', options:['Un roi de France','Un révolutionnaire républicain','Un président de la République','Un général de la Révolution devenu consul puis Empereur des Français'], answer:3, explanation:'Napoléon Bonaparte, général de la Révolution, devient Premier consul en 1799 puis Empereur des Français en 1804.' },
  { id:'q093', level:['CSP','CR'], topic:4, q:'Dans quelle République est-on aujourd\'hui ?', options:['La IIIe République','La IVe République','La VIe République','La Ve République'], answer:3, explanation:'La Ve République a été fondée en 1958 et est le régime républicain actuel de la France.' },
  { id:'q094', level:['CSP','CR'], topic:4, q:'Qu\'est-ce que la Shoah ?', options:['Une guerre entre pays européens','La Résistance française','La colonisation de l\'Afrique','Le génocide des Juifs d\'Europe perpétré par les nazis'], answer:3, explanation:'La Shoah désigne le génocide de 6 millions de Juifs européens planifié et exécuté par le régime nazi (1941–1945).' },
  { id:'q095', level:['CSP','CR'], topic:4, q:'Qui a fondé la Ve République ?', options:['Georges Pompidou','François Mitterrand','Valéry Giscard d\'Estaing','Charles de Gaulle'], answer:3, explanation:'Le général de Gaulle est le fondateur de la Ve République. La Constitution a été approuvée par référendum le 28 septembre 1958.' },
  { id:'q096', level:['CSP','CR'], topic:4, q:'En quelle année l\'esclavage a-t-il été aboli définitivement en France ?', options:['1794','1815','1905','1848'], answer:3, explanation:'L\'esclavage a été aboli définitivement en France par la loi du 27 avril 1848, portée par Victor Schoelcher.' },
  { id:'q097', level:['CSP','CR'], topic:4, q:'Qui a rendu l\'école gratuite, laïque et obligatoire ?', options:['Napoléon Bonaparte','Charles de Gaulle','Victor Hugo','Jules Ferry'], answer:3, explanation:'Jules Ferry, ministre de l\'Instruction publique, rend l\'école gratuite (1881), laïque et obligatoire (1882) pour tous les enfants.' },
  { id:'q098', level:['CSP','CR'], topic:4, q:'Quand a eu lieu la Seconde Guerre mondiale ?', options:['1914–1918','1940–1944','1936–1942','1939–1945'], answer:3, explanation:'La Seconde Guerre mondiale s\'est déroulée de septembre 1939 à septembre 1945, causant des dizaines de millions de morts.' },
  { id:'q099', level:['CSP','CR'], topic:4, q:'Le 11 novembre est un jour férié. À quoi correspond cette date ?', options:['La fin de la Seconde Guerre mondiale','La fête nationale française','La proclamation de la Ve République','L\'armistice de la Première Guerre mondiale'], answer:3, explanation:'Le 11 novembre 1918 marque l\'armistice qui met fin à la Première Guerre mondiale. Ce jour est férié en France.' },
  { id:'q100', level:['CSP','CR'], topic:4, q:'Qui a été le premier Président élu sous la Ve République ?', options:['Georges Pompidou','François Mitterrand','Valéry Giscard d\'Estaing','Charles de Gaulle'], answer:3, explanation:'Charles de Gaulle a été le premier président de la Ve République, élu au suffrage universel indirect en 1958 puis direct en 1965.' },
  { id:'q101', level:['CSP','CR'], topic:4, q:'Depuis quelle année l\'école publique est-elle gratuite ?', options:['1789','1905','1945','1881'], answer:3, explanation:'Jules Ferry rend l\'enseignement primaire public gratuit par la loi du 16 juin 1881.' },
  { id:'q102', level:['CSP','CR'], topic:4, q:'Combien y a-t-il eu de républiques en France ?', options:['3','4','6','5'], answer:3, explanation:'La France a connu cinq républiques : Ire (1792), IIe (1848), IIIe (1870), IVe (1946) et Ve (1958).' },
  { id:'q103', level:['CSP','CR'], topic:4, q:'Qui était le roi de France au moment de la Révolution française ?', options:['Louis XIV','Louis XV','Napoléon Ier','Louis XVI'], answer:3, explanation:'Louis XVI était roi de France en 1789. Il fut guillotiné le 21 janvier 1793 pendant la Révolution.' },
  { id:'q104', level:['CSP','CR'], topic:4, q:'Pourquoi l\'année 1958 est-elle importante pour la France ?', options:['C\'est la fin de la Seconde Guerre mondiale','C\'est l\'abolition de l\'esclavage','C\'est l\'entrée dans l\'Union européenne','C\'est la fondation de la Ve République et l\'adoption de la Constitution actuelle'], answer:3, explanation:'En 1958, suite à la crise algérienne, le général de Gaulle fonde la Ve République avec une nouvelle Constitution.' },
  { id:'q105', level:['CSP','CR'], topic:4, q:'Quelle est la capitale de la France ?', options:['Lyon','Marseille','Bordeaux','Paris'], answer:3, explanation:'Paris est la capitale de la France, siège du gouvernement, du Parlement et des grandes institutions républicaines.' },
  { id:'q106', level:['CSP','CR'], topic:4, q:'Sur quel continent se situe la France métropolitaine ?', options:['En Amérique','En Afrique','En Asie','En Europe'], answer:3, explanation:'La France métropolitaine est située en Europe occidentale, sur la péninsule ibérique septentrionale.' },
  { id:'q107', level:['CSP','CR'], topic:4, q:'Combien y a-t-il de régions en France métropolitaine ?', options:['22','18','96','13'], answer:3, explanation:'Depuis la réforme territoriale de 2016, la France métropolitaine compte 13 régions (auxquelles s\'ajoutent 5 régions d\'outre-mer).' },
  { id:'q108', level:['CSP','CR'], topic:4, q:'Quel fleuve coule en France ?', options:['Le Rhin','Le Danube','La Tamise','La Loire'], answer:3, explanation:'La Loire (1 013 km) est le fleuve le plus long de France. La Seine traverse Paris.' },
  { id:'q109', level:['CSP','CR'], topic:4, q:'Quel océan borde la côte ouest française ?', options:['L\'océan Indien','L\'océan Pacifique','L\'océan Arctique','L\'océan Atlantique'], answer:3, explanation:'La côte atlantique de la France s\'étend de la frontière espagnole au nord de la Bretagne et du Cotentin.' },
  { id:'q110', level:['CSP','CR'], topic:4, q:'Quelle est la mer au sud de la France métropolitaine ?', options:['La mer du Nord','La mer Baltique','La mer Adriatique','La mer Méditerranée'], answer:3, explanation:'La Méditerranée borde le sud de la France, de la frontière espagnole (Perpignan) à la frontière italienne (Menton).' },
  { id:'q111', level:['CSP','CR'], topic:4, q:'Quelle chaîne de montagnes est située entre la France et l\'Italie ?', options:['Les Pyrénées','Le Massif central','Les Vosges','Les Alpes'], answer:3, explanation:'Les Alpes séparent la France de l\'Italie et de la Suisse. Le mont Blanc (4 808 m) est le plus haut sommet d\'Europe occidentale.' },
  { id:'q112', level:['CSP','CR'], topic:4, q:'Qui était Molière ?', options:['Un peintre du XVIIe siècle','Un philosophe des Lumières','Un général de Napoléon','Un dramaturge et comédien français du XVIIe siècle'], answer:3, explanation:'Molière (1622–1673) est le plus célèbre dramaturge français. Auteur du Misanthrope, Tartuffe, L\'Avare…' },
  { id:'q113', level:['CSP','CR'], topic:4, q:'Qu\'est-ce que le Louvre ?', options:['Un monument commémoratif','Un palais présidentiel','La résidence du roi de France','Un musée parisien parmi les plus visités au monde'], answer:3, explanation:'Le musée du Louvre, situé dans l\'ancien palais royal de Paris, est le plus grand musée d\'art du monde.' },
  { id:'q114', level:['CSP','CR'], topic:4, q:'Dans quelle ville se trouve la tour Eiffel ?', options:['Lyon','Marseille','Bordeaux','Paris'], answer:3, explanation:'La tour Eiffel, construite en 1889 pour l\'Exposition universelle, est le monument le plus visité au monde.' },
  { id:'q115', level:['CSP','CR'], topic:4, q:'Quelle île est un département d\'outre-mer français ?', options:['La Corse','Madagascar','Tahiti','La Réunion'], answer:3, explanation:'La Réunion est un département et région d\'outre-mer (DROM) français situé dans l\'océan Indien.' },
  { id:'q116', level:['CSP','CR'], topic:4, q:'Qui était Albert Camus ?', options:['Un homme politique français','Un physicien prix Nobel','Un peintre impressionniste','Un écrivain et philosophe, prix Nobel de littérature 1957'], answer:3, explanation:'Albert Camus (1913–1960) est un écrivain et philosophe franco-algérien, auteur de L\'Étranger et La Peste.' },
  { id:'q117', level:['CSP','CR'], topic:4, q:'En quelle année a été créée la Communauté Économique Européenne (CEE) ?', options:['1945','1951','1992','1957'], answer:3, explanation:'La CEE a été créée par le Traité de Rome signé le 25 mars 1957, entré en vigueur en 1958.' },
  { id:'q118', level:['CSP','CR'], topic:4, q:'Quelle guerre a eu lieu entre 1914 et 1918 ?', options:['La guerre de Sécession','La Seconde Guerre mondiale','La guerre d\'Algérie','La Première Guerre mondiale'], answer:3, explanation:'La Première Guerre mondiale (1914–1918) a causé la mort de 18 millions de personnes. L\'armistice a été signé le 11 novembre 1918.' },
  { id:'q119', level:['CSP','CR'], topic:4, q:'Qui était Simone de Beauvoir ?', options:['Une actrice française','Une femme politique','Une artiste peintre','Une philosophe et écrivaine féministe'], answer:3, explanation:'Simone de Beauvoir (1908–1986) est une philosophe existentialiste et militante féministe, auteure du Deuxième Sexe.' },
  { id:'q120', level:['CSP','CR'], topic:4, q:'Quelle ville est un grand port maritime ?', options:['Strasbourg','Dijon','Clermont-Ferrand','Marseille'], answer:3, explanation:'Marseille est le premier port de France et de Méditerranée, et le deuxième d\'Europe.' },

  // ─── TOPIC 5 : Vivre dans la société française ──────────────────────────────
  { id:'q121', level:['CSP','CR'], topic:5, q:'Quel numéro d\'urgence permet d\'appeler le SAMU ?', options:['17','18','112','15'], answer:3, explanation:'Le 15 est le numéro du SAMU (Service d\'Aide Médicale Urgente). Gratuit et disponible 24h/24.' },
  { id:'q122', level:['CSP','CR'], topic:5, q:'Quel numéro d\'urgence permet d\'appeler les pompiers ?', options:['15','17','112','18'], answer:3, explanation:'Le 18 est le numéro des sapeurs-pompiers pour les incendies, accidents et urgences diverses.' },
  { id:'q123', level:['CSP','CR'], topic:5, q:'Après avoir obtenu le permis de conduire, que faut-il faire pour pouvoir conduire sa voiture ?', options:['Passer un test médical','Obtenir une autorisation préfectorale','Payer une taxe annuelle','Souscrire une assurance responsabilité civile'], answer:3, explanation:'L\'assurance responsabilité civile (au tiers) est obligatoire pour tout véhicule motorisé avant de circuler sur la voie publique.' },
  { id:'q124', level:['CSP','CR'], topic:5, q:'Le travail non déclaré est :', options:['Toléré pour les petits travaux','Autorisé entre particuliers','Légal si le montant est faible','Interdit et puni par la loi'], answer:3, explanation:'Le travail non déclaré (travail au noir) est illégal. Il prive le salarié de ses droits sociaux et constitue une fraude.' },
  { id:'q125', level:['CSP','CR'], topic:5, q:'Qu\'est-ce que le SMIC ?', options:['Un organisme d\'aide à l\'emploi','Un système de mutuelle santé','Une aide au logement','Le salaire minimum interprofessionnel de croissance'], answer:3, explanation:'Le SMIC est le salaire horaire en dessous duquel aucun employeur ne peut rémunérer un salarié en France.' },
  { id:'q126', level:['CSP','CR'], topic:5, q:'Quelle est la durée légale du temps de travail par semaine ?', options:['39 heures','40 heures','32 heures','35 heures'], answer:3, explanation:'La durée légale du travail est de 35 heures par semaine depuis la loi Aubry de 2000. Les heures supplémentaires sont majorées.' },
  { id:'q127', level:['CSP','CR'], topic:5, q:'Qui est aidé par France Travail ?', options:['Uniquement les chômeurs de longue durée','Seulement les citoyens français','Les personnes handicapées uniquement','Les demandeurs d\'emploi et les entreprises qui recrutent'], answer:3, explanation:'France Travail (ex-Pôle Emploi) accompagne les demandeurs d\'emploi dans leur recherche et aide les entreprises à recruter.' },
  { id:'q128', level:['CSP','CR'], topic:5, q:'À partir de quel âge un mineur peut-il travailler ?', options:['14 ans','18 ans','15 ans','16 ans'], answer:3, explanation:'Un mineur peut travailler à partir de 16 ans dans la plupart des cas. Des exceptions existent pour certaines activités dès 14 ans (jobs d\'été).' },
  { id:'q129', level:['CSP','CR'], topic:5, q:'Auprès de quel organisme faut-il demander le remboursement des frais de santé ?', options:['La mairie','Le médecin traitant','La mutuelle uniquement','L\'Assurance maladie (Sécurité sociale)'], answer:3, explanation:'L\'Assurance maladie rembourse une partie des frais de santé. La mutuelle complémentaire couvre le reste à charge.' },
  { id:'q130', level:['CSP','CR'], topic:5, q:'À quoi sert la carte Vitale ?', options:['À prouver son identité','À accéder aux transports en commun','À obtenir des réductions dans les commerces','À faciliter le remboursement des soins de santé'], answer:3, explanation:'La carte Vitale est la carte d\'assuré social. Elle permet la transmission électronique des feuilles de soins pour un remboursement rapide.' },
  { id:'q131', level:['CSP','CR'], topic:5, q:'Jusqu\'à quel âge l\'école est-elle obligatoire ?', options:['14 ans','18 ans','15 ans','16 ans'], answer:3, explanation:'L\'instruction est obligatoire jusqu\'à 16 ans en France. Elle peut se faire à l\'école ou, sous conditions, à domicile.' },
  { id:'q132', level:['CSP','CR'], topic:5, q:'Quel diplôme obtient-on à la fin du lycée ?', options:['Le BEP','Le BEPC','La licence','Le baccalauréat'], answer:3, explanation:'Le baccalauréat (bac) est le diplôme national obtenu à la fin du lycée. Il donne accès à l\'enseignement supérieur.' },
  { id:'q133', level:['CSP','CR'], topic:5, q:'Dans quels établissements scolaires vont les élèves après l\'école élémentaire ?', options:['Au lycée','À l\'université','À l\'école maternelle','Au collège'], answer:3, explanation:'Après l\'école primaire (élémentaire), les élèves entrent au collège (11–15 ans), puis au lycée (15–18 ans).' },
  { id:'q134', level:['CSP','CR'], topic:5, q:'En cas de problème de santé non urgent, à qui faut-il s\'adresser en premier ?', options:['Aux urgences de l\'hôpital','Au SAMU','À la pharmacie','Au médecin traitant'], answer:3, explanation:'Le médecin traitant est le premier interlocuteur dans le parcours de soins coordonné. Il oriente vers des spécialistes si nécessaire.' },
  { id:'q135', level:['CSP','CR'], topic:5, q:'À quoi sert une mutuelle santé ?', options:['À remplacer la Sécurité sociale','À financer uniquement les médicaments','À payer les urgences hospitalières','À compléter le remboursement de la Sécurité sociale'], answer:3, explanation:'La mutuelle (complémentaire santé) prend en charge le ticket modérateur et les dépassements d\'honoraires non remboursés par la Sécu.' },
  { id:'q136', level:['CSP','CR'], topic:5, q:'Pour qui l\'école est-elle obligatoire ?', options:['Seulement pour les enfants français','Pour les enfants de 6 à 14 ans','Seulement si les parents travaillent','Pour tous les enfants de 3 à 16 ans résidant en France'], answer:3, explanation:'L\'instruction est obligatoire pour tous les enfants résidant sur le territoire français, de 3 à 16 ans, quelle que soit leur nationalité.' },
  { id:'q137', level:['CSP','CR'], topic:5, q:'À quelles conditions un mariage est-il reconnu juridiquement ?', options:['Il suffit d\'une cérémonie religieuse','Il suffit d\'un contrat signé devant notaire','Il doit être validé par le préfet','Il doit être célébré en mairie devant un officier d\'état civil'], answer:3, explanation:'En France, seul le mariage civil célébré en mairie produit des effets juridiques. La cérémonie religieuse est facultative.' },
  { id:'q138', level:['CSP','CR'], topic:5, q:'Quand faut-il déclarer son enfant au service d\'état civil de la mairie ?', options:['Dans les 30 jours','Dans l\'année','Avant la naissance','Dans les 5 jours suivant la naissance'], answer:3, explanation:'La naissance doit être déclarée à la mairie du lieu d\'accouchement dans un délai de 5 jours après la naissance.' },
  { id:'q139', level:['CSP','CR'], topic:5, q:'Qu\'est-ce que le SAMU ?', options:['Le service d\'aide aux migrants','La police des frontières','Un organisme de sécurité sociale','Le Service d\'Aide Médicale Urgente, appelé au 15'], answer:3, explanation:'Le SAMU coordonne les secours médicaux d\'urgence et régule les appels au 15. Il envoie des équipes médicales sur les lieux.' },
  { id:'q140', level:['CSP','CR'], topic:5, q:'Une femme peut-elle créer son entreprise ?', options:['Non, il faut l\'accord du mari','Non, les femmes ne peuvent pas créer d\'entreprise','Oui, mais seulement dans certains secteurs','Oui, les femmes ont les mêmes droits que les hommes'], answer:3, explanation:'Le principe d\'égalité entre femmes et hommes garantit aux femmes les mêmes droits dans tous les domaines, y compris la création d\'entreprise.' },
  { id:'q141', level:['CSP','CR'], topic:5, q:'Quel est l\'objectif des vaccinations obligatoires ?', options:['Enrichir les laboratoires','Contrôler la population','Remplacer les traitements médicaux','Protéger la santé individuelle et collective'], answer:3, explanation:'Les vaccinations obligatoires visent à protéger les individus et à créer une immunité collective contre les maladies infectieuses graves.' },
  { id:'q142', level:['CSP','CR'], topic:5, q:'L\'autorité parentale prévoit l\'obligation :', options:['De travailler pour financer les études','D\'inscrire ses enfants dans une école religieuse','De choisir la religion de ses enfants','De scolariser les enfants et de subvenir à leurs besoins'], answer:3, explanation:'L\'autorité parentale oblige les parents à assurer l\'éducation, la sécurité, la santé et l\'instruction de leurs enfants.' },
  { id:'q143', level:['CSP','CR'], topic:5, q:'Les enfants qui ne parlent pas français :', options:['Ne peuvent pas être scolarisés','Doivent attendre de parler français avant l\'école','Sont placés dans des classes spéciales isolées','Peuvent être scolarisés et bénéficient d\'un soutien linguistique'], answer:3, explanation:'Tout enfant résidant en France a droit à l\'éducation. Les dispositifs UPE2A (unités pédagogiques) accompagnent les élèves allophones.' },
  { id:'q144', level:['CSP','CR'], topic:5, q:'Dans quelles situations doit-on se rendre aux urgences de l\'hôpital ?', options:['Pour tout problème de santé','Pour les consultations de routine','Quand le médecin traitant n\'est pas disponible','En cas d\'urgence médicale grave ou de danger immédiat'], answer:3, explanation:'Les urgences hospitalières sont réservées aux situations mettant en jeu la vie du patient ou nécessitant des soins immédiats.' },
  { id:'q145', level:['CSP','CR'], topic:5, q:'Quel est le rôle du médecin traitant ?', options:['Réaliser uniquement des opérations chirurgicales','Délivrer des médicaments directement','Gérer les remboursements de l\'Assurance maladie','Assurer le suivi médical de base et orienter vers des spécialistes'], answer:3, explanation:'Le médecin traitant est le pivot du parcours de soins : il suit le patient, prescrit des traitements et oriente vers des spécialistes.' },
  { id:'q146', level:['CSP','CR'], topic:5, q:'Quelle est la première démarche à réaliser pour chercher un emploi ?', options:['Déposer son CV à la mairie','Contacter son médecin','Envoyer directement des candidatures','S\'inscrire à France Travail'], answer:3, explanation:'L\'inscription à France Travail (ex-Pôle Emploi) est la première étape pour bénéficier d\'un accompagnement personnalisé et des aides à l\'emploi.' },
  { id:'q147', level:['CSP','CR'], topic:5, q:'Une personne étrangère en situation régulière peut créer son entreprise :', options:['Jamais, c\'est réservé aux Français','Seulement si elle est ressortissante de l\'UE','Après 10 ans de résidence uniquement','Oui, sous certaines conditions légales'], answer:3, explanation:'Un étranger en situation régulière peut créer une entreprise en France, sous réserve de disposer d\'un titre de séjour l\'y autorisant.' },
  { id:'q148', level:['CSP','CR'], topic:5, q:'Qu\'est-ce qu\'un numéro d\'urgence ?', options:['Un numéro payant pour les urgences','Un numéro réservé aux professionnels de santé','Un numéro réservé aux citoyens français','Un numéro gratuit permettant d\'appeler les services de secours'], answer:3, explanation:'Les numéros d\'urgence (15, 17, 18, 112) sont gratuits, accessibles depuis n\'importe quel téléphone, 24h/24 et 7j/7.' },
  { id:'q149', level:['CSP','CR'], topic:5, q:'Un enfant inscrit à l\'école :', options:['Peut manquer les cours si ses parents le souhaitent','Peut choisir de ne pas y aller','N\'est pas obligé d\'y assister s\'il apprend à la maison sans autorisation','Doit obligatoirement y aller, sauf maladie ou motif valable'], answer:3, explanation:'L\'assiduité scolaire est obligatoire. Toute absence doit être justifiée par les parents auprès de l\'établissement.' },
  { id:'q150', level:['CSP','CR'], topic:5, q:'Que doit faire un employeur pour fixer un salaire ?', options:['Il peut fixer le salaire qu\'il veut','Il doit demander l\'accord du gouvernement','Il doit payer le même salaire à tous','Il doit respecter le SMIC et les conventions collectives'], answer:3, explanation:'Le salaire doit être au moins égal au SMIC. Les conventions collectives peuvent prévoir des minima supérieurs selon le secteur.' },

  // ─── CR-ONLY QUESTIONS ───────────────────────────────────────────────────────
  // Topic 1 – CR only
  { id:'q151', level:['CR'], topic:1, q:'Parmi les propositions suivantes, laquelle constitue une participation citoyenne ?', options:['Regarder les informations à la télévision','Payer ses impôts','Aller au travail','Voter aux élections'], answer:3, explanation:'Voter est l\'acte citoyen par excellence dans une démocratie représentative. Il permet de choisir ses représentants.' },
  { id:'q152', level:['CR'], topic:1, q:'Que garantit la liberté d\'expression ?', options:['Le droit de proférer des insultes','Le droit de publier sans contrôle','Le droit de critiquer les juges sans limite','Le droit d\'exprimer librement ses opinions dans le respect des lois'], answer:3, explanation:'La liberté d\'expression garantit le droit de s\'exprimer librement, sous réserve de ne pas porter atteinte aux droits d\'autrui.' },
  { id:'q153', level:['CR'], topic:1, q:'À quoi sert un titre de séjour ?', options:['À prouver qu\'on parle français','À permettre de travailler uniquement','À obtenir la nationalité française','À autoriser légalement un étranger à résider en France'], answer:3, explanation:'Le titre de séjour est le document attestant qu\'un ressortissant étranger a le droit de séjourner régulièrement en France.' },
  { id:'q154', level:['CR'], topic:1, q:'Complétez ces paroles de la Marseillaise : "Aux armes [...] ! Formez vos bataillons"', options:['soldats','guerriers','défenseurs','citoyens'], answer:3, explanation:'"Aux armes, citoyens ! Formez vos bataillons !" est le refrain de La Marseillaise, hymne national depuis 1795.' },
  { id:'q155', level:['CR'], topic:1, q:'La répudiation de sa femme est :', options:['Autorisée si les deux conjoints sont d\'accord','Autorisée selon certaines traditions','Autorisée avec l\'accord du juge','Interdite en France'], answer:3, explanation:'La répudiation unilatérale du mariage est contraire aux lois françaises. Seul le divorce judiciaire ou par consentement mutuel est légal.' },
  { id:'q156', level:['CR'], topic:1, q:'Peut-on brûler publiquement un drapeau français ?', options:['Oui, c\'est de la liberté d\'expression','Oui, lors d\'une manifestation autorisée','Oui, si c\'est fait de façon artistique','Non, c\'est une infraction pénale'], answer:3, explanation:'Brûler ou dégrader le drapeau national en public est un délit puni par la loi française.' },
  { id:'q157', level:['CR'], topic:1, q:'Que représente Marianne ?', options:['La reine de France','La patronne des armées','La figure de la résistance','Le symbole de la République française'], answer:3, explanation:'Marianne incarne la République française, ses valeurs de liberté et de raison. Elle figure sur les timbres et dans les mairies.' },
  { id:'q158', level:['CR'], topic:1, q:'Qu\'est-ce que la liberté d\'association ?', options:['Le droit de s\'associer avec des entreprises étrangères','Le droit de ne pas adhérer à un syndicat','Le droit de créer un parti politique uniquement','Le droit de créer et rejoindre librement des associations'], answer:3, explanation:'La liberté d\'association (loi 1901) permet à tout citoyen de créer ou rejoindre une association de son choix.' },
  { id:'q159', level:['CR'], topic:1, q:'Selon le principe de laïcité, que signifie la neutralité de l\'État ?', options:['L\'État favorise la religion catholique','L\'État interdit toute pratique religieuse','L\'État subventionne toutes les religions','L\'État n\'a pas de religion officielle et traite toutes les convictions de façon égale'], answer:3, explanation:'La neutralité de l\'État signifie que les services publics ne favorisent ni ne combattent aucune religion.' },
  { id:'q160', level:['CR'], topic:1, q:'Que dit l\'article 1er de la Constitution française ?', options:['"La France est une monarchie parlementaire"','"La souveraineté appartient au roi de France"','"La France est un État fédéral"','"La France est une République indivisible, laïque, démocratique et sociale"'], answer:3, explanation:'L\'article 1er de la Constitution de 1958 définit la nature de la République française : indivisible, laïque, démocratique et sociale.' },
  { id:'q161', level:['CR'], topic:1, q:'À l\'école publique, qui peut porter des signes religieux très visibles ?', options:['Les enseignants uniquement','Les élèves uniquement','Les parents accompagnateurs uniquement','Personne — ni les élèves ni le personnel de l\'école'], answer:3, explanation:'La loi du 15 mars 2004 interdit aux élèves de porter des signes religieux ostensibles. Le personnel est soumis au principe de neutralité.' },
  { id:'q162', level:['CR'], topic:1, q:'Que peut faire un usager du service public dans une mairie ?', options:['Imposer ses convictions religieuses aux agents','Refuser d\'être servi par un agent d\'une autre religion','Exiger que les agents fassent de même','Accomplir ses démarches administratives dans le respect de la neutralité du service'], answer:3, explanation:'Un usager peut se rendre dans une mairie avec des signes religieux, mais ne peut pas entraver le fonctionnement du service public.' },
  { id:'q163', level:['CR'], topic:1, q:'Que garantit le principe de laïcité ?', options:['L\'interdiction de toute pratique religieuse','L\'obligation de pratiquer une religion','La supériorité du catholicisme','La liberté de conscience et l\'égalité de traitement de tous'], answer:3, explanation:'La laïcité garantit la liberté de conscience pour tous : croire, ne pas croire, pratiquer ou changer de religion librement.' },
  { id:'q164', level:['CR'], topic:1, q:'En application de la liberté individuelle, quelle proposition est correcte ?', options:['On peut imposer sa religion à ses enfants','On peut refuser de respecter la loi','On peut s\'exonérer de payer des impôts','On peut circuler librement sur le territoire français'], answer:3, explanation:'La liberté de circulation est une liberté fondamentale permettant à toute personne de se déplacer librement sur le territoire.' },
  { id:'q165', level:['CR'], topic:1, q:'Un employeur refuse d\'embaucher des femmes dans son entreprise. Que dit la loi ?', options:['C\'est autorisé pour des raisons pratiques','C\'est autorisé dans certains secteurs','C\'est autorisé si l\'entreprise est petite','C\'est une discrimination illégale'], answer:3, explanation:'La loi interdit toute discrimination à l\'embauche fondée sur le sexe. Tout employeur contrevenant s\'expose à des sanctions pénales.' },
  { id:'q166', level:['CR'], topic:1, q:'Les impôts permettent de financer les dépenses publiques. Quelle proposition est correcte ?', options:['Seuls les riches paient des impôts','Les étrangers ne paient pas d\'impôts en France','On peut refuser de payer ses impôts','Payer ses impôts est une obligation pour toutes les personnes résidant en France'], answer:3, explanation:'Toute personne résidant en France et percevant des revenus est soumise à l\'obligation fiscale, quelle que soit sa nationalité.' },
  { id:'q167', level:['CR'], topic:1, q:'Qui doit respecter le principe de neutralité religieuse dans une préfecture ?', options:['Les usagers du service public','Tout le monde, y compris les visiteurs','Uniquement les directeurs','Les agents et fonctionnaires de la préfecture'], answer:3, explanation:'Le principe de neutralité s\'impose aux agents de la fonction publique, qui ne peuvent afficher aucun signe religieux en service.' },
  { id:'q168', level:['CR'], topic:1, q:'Qu\'est-ce qui est interdit par la Charte de la laïcité à l\'école ?', options:['Les cours d\'éducation civique','Les activités sportives mixtes','L\'enseignement des religions en cours d\'histoire','Le port de signes ou tenues manifestant ostensiblement une appartenance religieuse'], answer:3, explanation:'La Charte de la laïcité à l\'école, affichée dans tous les établissements, interdit les signes religieux ostensibles pour les élèves.' },
  { id:'q169', level:['CR'], topic:1, q:'La liberté de circulation permet à toute personne de :', options:['Se déplacer sans papiers d\'identité','Entrer sur le territoire de n\'importe quel pays','Conduire sans permis','Se déplacer librement sur le territoire français'], answer:3, explanation:'La liberté de circulation garantit le droit de se déplacer librement à l\'intérieur du territoire, dans le respect des lois.' },
  { id:'q170', level:['CR'], topic:1, q:'En tant que parent, peut-on refuser que son enfant participe aux cours de sport à l\'école car ils sont mixtes ?', options:['Oui, c\'est un droit parental','Oui, pour des raisons religieuses','Oui, avec l\'accord du directeur','Non, la mixité à l\'école est un principe républicain'], answer:3, explanation:'La mixité dans les établissements scolaires est un principe républicain. Les parents ne peuvent pas s\'y opposer pour des motifs religieux.' },

  // Topic 2 – CR only
  { id:'q171', level:['CR'], topic:2, q:'Qu\'est-ce que l\'État de droit ?', options:['Un État où le gouvernement est au-dessus des lois','Un État où les juges font les lois','Un État où les militaires gouvernent','Un État où tout le monde, y compris les dirigeants, est soumis à la loi'], answer:3, explanation:'L\'État de droit signifie que les pouvoirs publics sont eux-mêmes soumis au respect du droit et de la Constitution.' },
  { id:'q172', level:['CR'], topic:2, q:'La loi est l\'expression de :', options:['La volonté du président','La décision des juges','Les directives du gouvernement','La volonté du peuple, exprimée par ses représentants au Parlement'], answer:3, explanation:'Dans une démocratie représentative, la loi exprime la volonté générale à travers les représentants élus au Parlement.' },
  { id:'q173', level:['CR'], topic:2, q:'Est-ce que le vote est obligatoire ?', options:['Oui, c\'est une obligation légale','Oui, sous peine d\'amende','Oui, lors des élections présidentielles uniquement','Non, voter est un droit mais pas une obligation en France'], answer:3, explanation:'Le vote est un droit civique et une liberté en France. Il n\'est pas légalement obligatoire, contrairement à d\'autres pays.' },
  { id:'q174', level:['CR'], topic:2, q:'Qui dirige l\'action du Gouvernement ?', options:['Le président de la République','Le ministre de l\'Intérieur','Le président de l\'Assemblée nationale','Le Premier ministre'], answer:3, explanation:'Selon l\'article 21 de la Constitution, le Premier ministre dirige l\'action du gouvernement depuis l\'Hôtel de Matignon.' },
  { id:'q175', level:['CR'], topic:2, q:'Quel est le rôle du Défenseur des droits ?', options:['Défendre la France dans les conflits','Voter les lois protégeant les droits','Former les avocats de la défense','Protéger les citoyens contre les manquements des services publics et les discriminations'], answer:3, explanation:'Le Défenseur des droits est une autorité constitutionnelle indépendante qui défend les droits des personnes face aux institutions.' },
  { id:'q176', level:['CR'], topic:2, q:'Quel est le rôle principal du département ?', options:['Gérer les affaires de politique étrangère','Voter les lois','Représenter la France à l\'étranger','Gérer les affaires locales : aide sociale, routes, collèges'], answer:3, explanation:'Le conseil départemental gère l\'action sociale, l\'entretien des routes départementales et la construction des collèges.' },
  { id:'q177', level:['CR'], topic:2, q:'Combien de communes environ existe-t-il en France ?', options:['10 000','100 000','5 000','36 000'], answer:3, explanation:'La France compte environ 35 000 communes, ce qui en fait le pays de l\'UE avec le plus grand nombre de communes.' },
  { id:'q178', level:['CR'], topic:2, q:'Quel État a quitté l\'Union européenne en 2020 ?', options:['La Norvège','La Suisse','La Turquie','Le Royaume-Uni'], answer:3, explanation:'Le Brexit a officiellement pris effet le 31 janvier 2020 après le référendum britannique de 2016.' },
  { id:'q179', level:['CR'], topic:2, q:'Quelle est la devise de l\'Union européenne ?', options:['"Liberté, égalité, fraternité"','"Paix et prospérité"','"Force par l\'unité"','"Unie dans la diversité"'], answer:3, explanation:'La devise de l\'Union européenne est "Unie dans la diversité", adoptée en 2000.' },
  { id:'q180', level:['CR'], topic:2, q:'En quelle année le traité de Maastricht a-t-il été signé ?', options:['1957','2004','1986','1992'], answer:3, explanation:'Le traité de Maastricht, signé le 7 février 1992, a fondé l\'Union européenne et créé la citoyenneté européenne.' },
  { id:'q181', level:['CR'], topic:2, q:'Où est le siège du Parlement européen ?', options:['Paris','Berlin','Luxembourg','Bruxelles et Strasbourg'], answer:3, explanation:'Le Parlement européen a son siège officiel à Strasbourg, avec des séances plénières supplémentaires à Bruxelles.' },
  { id:'q182', level:['CR'], topic:2, q:'Qu\'est-ce que l\'Hôtel de Matignon ?', options:['Le palais présidentiel','Le siège de l\'Assemblée nationale','Le palais de justice de Paris','La résidence officielle du Premier ministre'], answer:3, explanation:'L\'Hôtel de Matignon est la résidence et le bureau officiel du Premier ministre, situé dans le 7e arrondissement de Paris.' },
  { id:'q183', level:['CR'], topic:2, q:'Quel est le rôle du président de la République ?', options:['Voter les lois','Gérer les services communaux','Juger les affaires criminelles','Garantir le fonctionnement des institutions, représenter la France et nommer le Premier ministre'], answer:3, explanation:'Le président de la République est le garant de la Constitution, de l\'indépendance nationale et de l\'intégrité du territoire.' },
  { id:'q184', level:['CR'], topic:2, q:'Quel est le rôle du Premier ministre ?', options:['Représenter la France à l\'étranger','Voter les lois au Parlement','Élire les membres du Conseil constitutionnel','Diriger l\'action du gouvernement et coordonner les ministres'], answer:3, explanation:'Le Premier ministre dirige le gouvernement, coordonne l\'action des ministres et est responsable devant l\'Assemblée nationale.' },
  { id:'q185', level:['CR'], topic:2, q:'Quel est le rôle principal des communes ?', options:['Gérer les affaires nationales','Voter les lois','Percevoir les impôts nationaux','Gérer les services de proximité : état civil, urbanisme, écoles maternelles et primaires'], answer:3, explanation:'Les communes ont compétence sur l\'état civil, le PLU, les crèches, les écoles primaires et les équipements sportifs et culturels.' },
  { id:'q186', level:['CR'], topic:2, q:'Quel est l\'hymne de l\'Union européenne ?', options:['La Marseillaise','La 5e symphonie de Beethoven','Europa Europa','L\'Ode à la joie (9e symphonie de Beethoven)'], answer:3, explanation:'L\'Ode à la joie, tiré de la 9e symphonie de Beethoven, est l\'hymne officiel de l\'Union européenne depuis 1985.' },
  { id:'q187', level:['CR'], topic:2, q:'Quelle est la durée du mandat du maire ?', options:['4 ans','5 ans','7 ans','6 ans'], answer:3, explanation:'Le maire et le conseil municipal sont élus pour un mandat de 6 ans lors des élections municipales.' },
  { id:'q188', level:['CR'], topic:2, q:'Pourquoi séparer les trois pouvoirs dans une démocratie ?', options:['Pour ralentir la prise de décision','Pour que le président ait plus d\'autorité','Pour simplifier l\'administration','Pour éviter les abus de pouvoir et garantir les libertés'], answer:3, explanation:'La séparation des pouvoirs, théorisée par Montesquieu, vise à prévenir la tyrannie en équilibrant les pouvoirs entre différentes institutions.' },
  { id:'q189', level:['CR'], topic:2, q:'Depuis quand l\'euro est-il la monnaie unique utilisée en France ?', options:['1992','1999','1986','2002'], answer:3, explanation:'Les pièces et billets en euros ont été mis en circulation le 1er janvier 2002 dans 12 pays de la zone euro.' },
  { id:'q190', level:['CR'], topic:2, q:'Combien y a-t-il de régions en France (métropole + outre-mer) ?', options:['13','18','22','26'], answer:1, explanation:'La France compte 13 régions métropolitaines et 5 régions d\'outre-mer, soit 18 régions au total.' },

  // Topic 3 – CR only
  { id:'q191', level:['CR'], topic:3, q:'Que contient la Constitution ?', options:['Uniquement les droits des citoyens','Uniquement les devoirs des citoyens','Les lois ordinaires et règlements','Les règles d\'organisation de l\'État et les droits fondamentaux'], answer:3, explanation:'La Constitution est la loi suprême. Elle fixe les règles d\'organisation des pouvoirs publics et garantit les droits fondamentaux.' },
  { id:'q192', level:['CR'], topic:3, q:'Que garantit la liberté de la presse ?', options:['Le droit de publier sans payer d\'impôts','Le droit de critiquer n\'importe qui','Le droit de posséder un journal','La possibilité d\'informer le public librement dans le respect des lois'], answer:3, explanation:'La liberté de la presse permet aux journalistes d\'enquêter et d\'informer librement, sans censure préalable de l\'État.' },
  { id:'q193', level:['CR'], topic:3, q:'Que prévoit la Charte de l\'environnement ?', options:['L\'interdiction de toute activité industrielle','L\'obligation de recycler tous ses déchets','La nationalisation des ressources naturelles','La protection de l\'environnement comme droit fondamental de valeur constitutionnelle'], answer:3, explanation:'La Charte de l\'environnement de 2004 a été intégrée au bloc de constitutionnalité. Elle consacre le droit à un environnement sain.' },
  { id:'q194', level:['CR'], topic:3, q:'Que signifie la dignité humaine ?', options:['L\'obligation d\'être poli en public','Le droit de vivre dans un logement de luxe','L\'interdiction de critiquer autrui','Le droit d\'être traité avec respect, sans être rabaissé ou humilié'], answer:3, explanation:'La dignité humaine est un droit fondamental inaliénable : chaque personne mérite d\'être traitée avec respect, quelles que soient ses origines.' },
  { id:'q195', level:['CR'], topic:3, q:'Que signifie le droit de manifester ?', options:['Le droit de bloquer les routes indéfiniment','Le droit de refuser de payer ses impôts','Le droit de forcer les parlementaires à voter','Le droit de s\'exprimer collectivement dans l\'espace public pour défendre une cause'], answer:3, explanation:'La liberté de manifestation permet de se réunir pacifiquement dans l\'espace public pour exprimer une opinion collective.' },
  { id:'q196', level:['CR'], topic:3, q:'Qu\'est-ce que le droit de grève ?', options:['Le droit de ne pas aller travailler quand on le souhaite','Le droit d\'insulter son employeur','Le droit de s\'absenter sans en informer son employeur','Le droit de cesser collectivement le travail pour défendre des revendications professionnelles'], answer:3, explanation:'Le droit de grève est constitutionnellement reconnu. Il permet aux salariés d\'arrêter le travail collectivement pour défendre leurs droits.' },
  { id:'q197', level:['CR'], topic:3, q:'L\'État peut-il limiter les droits et libertés ?', options:['Non, jamais — les droits sont absolus','Oui, de façon arbitraire','Oui, mais seulement pour les étrangers','Oui, dans certains cas pour protéger l\'ordre public ou les droits d\'autrui'], answer:3, explanation:'Les libertés ne sont pas absolues. Des restrictions légales sont possibles si elles sont nécessaires, proportionnées et non discriminatoires.' },
  { id:'q198', level:['CR'], topic:3, q:'Pour quel motif peut-on limiter la liberté d\'expression ?', options:['Pour protéger les intérêts économiques du gouvernement','Pour empêcher les critiques politiques','On ne peut jamais la limiter','Pour prévenir l\'incitation à la haine, la diffamation ou les atteintes à la dignité'], answer:3, explanation:'La liberté d\'expression peut être limitée pour prévenir des discours de haine, des propos diffamatoires ou des appels à la violence.' },
  { id:'q199', level:['CR'], topic:3, q:'Quel texte est le plus difficile à modifier ?', options:['Une loi ordinaire','Un décret gouvernemental','Un règlement municipal','La Constitution'], answer:3, explanation:'La Constitution est la norme suprême. Sa révision nécessite un vote du Parlement réuni en Congrès ou un référendum.' },
  { id:'q200', level:['CR'], topic:3, q:'Que signifie PMA ?', options:['Parcours Médical Annuel','Programme de Médecine Avancée','Prescription Médicale Automatique','Procréation Médicalement Assistée'], answer:3, explanation:'La PMA (Procréation Médicalement Assistée) désigne les techniques médicales permettant de concevoir un enfant en dehors de la conception naturelle.' },
  { id:'q201', level:['CR'], topic:3, q:'Quelle proposition représente un exemple de crime ?', options:['Excéder la vitesse de 10 km/h','Voler un téléphone portable','Une insulte en public','Un meurtre prémédité (assassinat)'], answer:3, explanation:'Un crime est la catégorie la plus grave d\'infraction, jugée par la cour d\'assises. L\'assassinat est un crime.' },
  { id:'q202', level:['CR'], topic:3, q:'Quelle proposition représente un exemple de délit ?', options:['Un excès de vitesse de 5 km/h','Un stationnement interdit','Un assassinat','Le vol avec violence'], answer:3, explanation:'Un délit est une infraction de gravité intermédiaire (entre contravention et crime), jugée par le tribunal correctionnel.' },
  { id:'q203', level:['CR'], topic:3, q:'Quel est un exemple d\'assistance à personne en danger ?', options:['Appeler la police pour dénoncer un voisin','Refuser de témoigner lors d\'un procès','Éviter de s\'approcher d\'un accident','Appeler le 15 pour une personne inconsciente dans la rue'], answer:3, explanation:'Appeler les secours pour une personne inconsciente est un acte d\'assistance obligatoire. Ne pas le faire constitue un délit.' },
  { id:'q204', level:['CR'], topic:3, q:'Concernant l\'utilisation des réseaux sociaux, quelle proposition est correcte ?', options:['On peut publier tout ce qu\'on veut','La loi ne s\'applique pas sur internet','On peut copier librement toutes les œuvres','Publier des propos haineux ou diffamatoires est interdit et punissable'], answer:3, explanation:'La loi française s\'applique sur internet. Les propos haineux, diffamatoires ou portant atteinte à la vie privée sont punis.' },
  { id:'q205', level:['CR'], topic:3, q:'Au nom de quoi l\'État justifie-t-il la restriction des droits ?', options:['De ses propres intérêts politiques','De la volonté du président','Des exigences économiques','De la protection de l\'ordre public, de la sécurité et des droits d\'autrui'], answer:3, explanation:'Toute restriction de liberté doit être justifiée par la nécessité de protéger l\'ordre public ou les droits et libertés d\'autrui.' },
  { id:'q206', level:['CR'], topic:3, q:'Quelle est l\'attitude à avoir lorsqu\'on est témoin de violences ?', options:['S\'éloigner pour ne pas être impliqué','Participer si on est du bon côté','Prendre des photos uniquement','Appeler les secours ou la police et aider la victime si on peut le faire en sécurité'], answer:3, explanation:'Être témoin de violences crée une obligation morale et légale d\'alerter les secours et d\'aider la victime si possible.' },
  { id:'q207', level:['CR'], topic:3, q:'Quelle liberté permet à une personne de croire en la religion de son choix ?', options:['La liberté d\'expression','La liberté d\'association','La liberté de circulation','La liberté de conscience et de religion'], answer:3, explanation:'La liberté de conscience et de religion, garantie par la laïcité, permet de croire en la religion de son choix ou de n\'en pratiquer aucune.' },
  { id:'q208', level:['CR'], topic:3, q:'Qu\'est-ce que la Constitution ?', options:['Un recueil de lois ordinaires','Un traité international signé par la France','Un règlement administratif','La loi fondamentale qui organise les pouvoirs de l\'État et garantit les droits fondamentaux'], answer:3, explanation:'La Constitution est la norme suprême de l\'État. Toutes les autres lois doivent lui être conformes.' },
  { id:'q209', level:['CR'], topic:3, q:'Parmi ces actions, laquelle permet d\'adopter une attitude respectueuse de l\'environnement ?', options:['Brûler ses déchets dans son jardin','Jeter ses déchets dans un cours d\'eau','Utiliser des emballages à usage unique systématiquement','Trier ses déchets et réduire sa consommation'], answer:3, explanation:'Trier ses déchets, réduire les emballages et consommer de manière responsable sont des gestes citoyens pour l\'environnement.' },
  { id:'q210', level:['CR'], topic:3, q:'S\'agissant des déchets, quelle proposition est correcte ?', options:['On peut jeter n\'importe quoi dans n\'importe quelle poubelle','Les déchets industriels et ménagers peuvent être mélangés','Les entreprises ne sont pas concernées par le tri','Le tri sélectif est obligatoire et permet de recycler les matières'], answer:3, explanation:'Le tri sélectif est obligatoire en France depuis plusieurs décennies. Il permet de recycler les matières et de réduire les déchets mis en décharge.' },

  // Topic 4 – CR only
  { id:'q211', level:['CR'], topic:4, q:'Quel était le surnom de Louis XIV ?', options:['Le Roi Chevalier','Le Grand Roi','Le Roi de fer','Le Roi Soleil'], answer:3, explanation:'Louis XIV (1638–1715) est surnommé le "Roi Soleil" en raison de son pouvoir absolu et de la splendeur de sa cour à Versailles.' },
  { id:'q212', level:['CR'], topic:4, q:'En quelle année Napoléon Ier est-il devenu emperor ?', options:['1789','1799','1815','1804'], answer:3, explanation:'Napoléon Bonaparte se proclame Empereur des Français le 2 décembre 1804, lors de son sacre à Notre-Dame de Paris.' },
  { id:'q213', level:['CR'], topic:4, q:'De quand date l\'appel à la résistance du général de Gaulle ?', options:['Le 8 mai 1945','Le 6 juin 1944','Le 11 novembre 1918','Le 18 juin 1940'], answer:3, explanation:'Le 18 juin 1940, depuis Londres, le général de Gaulle appelle les Français à continuer le combat contre l\'Allemagne nazie.' },
  { id:'q214', level:['CR'], topic:4, q:'Depuis quand les Français élisent-ils le président de la République au suffrage universel direct ?', options:['Depuis 1848','Depuis 1945','Depuis 1958','Depuis 1962'], answer:3, explanation:'Depuis la révision constitutionnelle de 1962, le président est élu au suffrage universel direct. La première élection directe date de 1965.' },
  { id:'q215', level:['CR'], topic:4, q:'Quelle est la première étape de la construction européenne en 1951 ?', options:['La création de l\'Union européenne','La création de la CEE','La signature du traité de Maastricht','La création de la Communauté Européenne du Charbon et de l\'Acier (CECA)'], answer:3, explanation:'La CECA, créée par le traité de Paris (1951) entre 6 pays, est la première organisation supranationale européenne. Elle est à l\'origine de l\'UE.' },
  { id:'q216', level:['CR'], topic:4, q:'Durant le mandat de quel président la peine de mort a-t-elle été abolie ?', options:['Georges Pompidou','Valéry Giscard d\'Estaing','Jacques Chirac','François Mitterrand'], answer:3, explanation:'La peine de mort a été abolie le 9 octobre 1981 par la loi Badinter, sous la présidence de François Mitterrand.' },
  { id:'q217', level:['CR'], topic:4, q:'En 1944, qu\'est-ce qui a changé pour les femmes ?', options:['L\'accès au travail','Le droit à l\'éducation','Le droit de divorcer','Le droit de vote'], answer:3, explanation:'L\'ordonnance du 21 avril 1944 accorde le droit de vote aux femmes françaises. Elles l\'exercent pour la première fois en 1945.' },
  { id:'q218', level:['CR'], topic:4, q:'Quelle organisation internationale a été créée en 1945 après la Seconde Guerre mondiale ?', options:['L\'Union européenne','L\'OTAN','La CEE','L\'Organisation des Nations Unies (ONU)'], answer:3, explanation:'L\'ONU a été fondée le 24 octobre 1945 pour maintenir la paix internationale et développer des relations amicales entre nations.' },
  { id:'q219', level:['CR'], topic:4, q:'Où a eu lieu le débarquement en 1944 ?', options:['En Provence','En Bretagne','Dans le Pas-de-Calais','En Normandie'], answer:3, explanation:'Le débarquement allié en Normandie (opération Overlord) a eu lieu le 6 juin 1944. Il marque le tournant décisif de la guerre en Europe.' },
  { id:'q220', level:['CR'], topic:4, q:'Que fête-t-on le 8 mai ?', options:['La fin de la Première Guerre mondiale','La fête du travail','Le débarquement en Normandie','La capitulation de l\'Allemagne nazie et la fin de la Seconde Guerre mondiale en Europe'], answer:3, explanation:'Le 8 mai 1945 marque la capitulation de l\'Allemagne nazie. Ce jour est férié en France en mémoire des victimes de la guerre.' },
  { id:'q221', level:['CR'], topic:4, q:'Quelle mer se situe entre la France et l\'Angleterre ?', options:['La mer du Nord','La mer Baltique','La mer Méditerranée','La Manche'], answer:3, explanation:'La Manche (English Channel) sépare la France du Royaume-Uni. Elle est reliée par le tunnel sous la Manche depuis 1994.' },
  { id:'q222', level:['CR'], topic:4, q:'Quelle chaîne de montagnes est située entre la France et l\'Espagne ?', options:['Les Alpes','Les Vosges','Le Massif central','Les Pyrénées'], answer:3, explanation:'Les Pyrénées forment la frontière naturelle entre la France et l\'Espagne, de l\'Atlantique à la Méditerranée.' },
  { id:'q223', level:['CR'], topic:4, q:'Quel fleuve traverse Paris ?', options:['La Loire','Le Rhône','La Garonne','La Seine'], answer:3, explanation:'La Seine traverse Paris sur environ 12,5 km. Elle est classée au patrimoine mondial de l\'UNESCO avec ses berges.' },
  { id:'q224', level:['CR'], topic:4, q:'Quelle est la population approximative de la France en 2025 ?', options:['55 millions','75 millions','80 millions','68 millions'], answer:3, explanation:'La France métropolitaine et les DROM comptent environ 68 millions d\'habitants en 2025.' },
  { id:'q225', level:['CR'], topic:4, q:'Quelle cathédrale célèbre a été en partie détruite par un incendie en 2019 ?', options:['La basilique du Sacré-Cœur','La cathédrale de Chartres','La cathédrale de Reims','Notre-Dame de Paris'], answer:3, explanation:'Notre-Dame de Paris a été en partie détruite par un incendie le 15 avril 2019. Sa restauration est en cours.' },
  { id:'q226', level:['CR'], topic:4, q:'Qui était Marguerite Yourcenar ?', options:['Une peintre impressionniste','Une physicienne prix Nobel','Une militante pour le droit de vote','La première femme élue à l\'Académie française'], answer:3, explanation:'Marguerite Yourcenar est devenue en 1980 la première femme élue à l\'Académie française, fondée en 1635.' },
  { id:'q227', level:['CR'], topic:4, q:'Qui était Auguste Rodin ?', options:['Un peintre impressionniste','Un compositeur romantique','Un architecte de la tour Eiffel','Un sculpteur français célèbre'], answer:3, explanation:'Auguste Rodin (1840–1917) est l\'un des plus grands sculpteurs français. Il est l\'auteur du Penseur et du Baiser.' },
  { id:'q228', level:['CR'], topic:4, q:'Combien de personnes parlent français dans le monde ?', options:['Environ 100 millions','Environ 500 millions','Environ 1 milliard','Environ 300 millions'], answer:3, explanation:'Le français est parlé par environ 300 millions de personnes dans le monde, sur tous les continents.' },
  { id:'q229', level:['CR'], topic:4, q:'Quel pays a une frontière terrestre avec la France métropolitaine au nord-est ?', options:['L\'Espagne','L\'Italie','Le Royaume-Uni','La Belgique et le Luxembourg'], answer:3, explanation:'Au nord-est, la France partage ses frontières avec la Belgique et le Luxembourg, puis l\'Allemagne et la Suisse.' },
  { id:'q230', level:['CR'], topic:4, q:'Quel régime politique a été mis en place pendant la Révolution française en 1792 ?', options:['La monarchie constitutionnelle','L\'Empire','La dictature militaire','La Première République'], answer:3, explanation:'La Première République française a été proclamée le 21 septembre 1792, après la chute de la monarchie.' },

  // Topic 5 – CR only
  { id:'q231', level:['CR'], topic:5, q:'Quel mariage est reconnu par l\'État ?', options:['Uniquement le mariage religieux','Le mariage célébré dans n\'importe quel lieu','Le mariage validé par le préfet','Le mariage civil célébré en mairie'], answer:3, explanation:'Seul le mariage civil célébré devant l\'officier d\'état civil de la mairie produit des effets juridiques en France.' },
  { id:'q232', level:['CR'], topic:5, q:'En cas de divorce, qui exerce l\'autorité parentale ?', options:['Uniquement le parent qui a la garde','Uniquement le père','L\'État, jusqu\'à la fin du divorce','Les deux parents conjointement, sauf décision contraire du juge'], answer:3, explanation:'Le divorce ne met pas fin à l\'autorité parentale conjointe. Les deux parents restent responsables de leurs enfants.' },
  { id:'q233', level:['CR'], topic:5, q:'Quelle aide permet aux personnes qui ont des difficultés financières d\'avoir un avocat ?', options:['L\'aide médicale d\'État (AME)','Le RSA','La protection universelle maladie (PUMA)','L\'aide juridictionnelle'], answer:3, explanation:'L\'aide juridictionnelle permet aux personnes aux revenus modestes d\'accéder à la justice avec un avocat pris en charge par l\'État.' },
  { id:'q234', level:['CR'], topic:5, q:'Quelle est l\'une des conditions pour passer l\'examen du permis de conduire ?', options:['Avoir au moins 20 ans','Résider en France depuis plus de 5 ans','Avoir une voiture à son nom','Avoir effectué une formation théorique (code de la route)'], answer:3, explanation:'La réussite du code de la route (épreuve théorique générale) est obligatoire avant de passer l\'épreuve pratique du permis.' },
  { id:'q235', level:['CR'], topic:5, q:'Un bail locatif est valide s\'il est :', options:['Verbal, avec témoins','Signé par le propriétaire seulement','Validé par la mairie','Écrit et signé par le propriétaire et le locataire'], answer:3, explanation:'Le contrat de location doit être écrit et signé par les deux parties pour être juridiquement opposable.' },
  { id:'q236', level:['CR'], topic:5, q:'Quel numéro d\'urgence permet d\'appeler la police ?', options:['15','18','112','17'], answer:3, explanation:'Le 17 est le numéro de la police secours et de la gendarmerie nationale pour les urgences sécurité.' },
  { id:'q237', level:['CR'], topic:5, q:'L\'inscription à l\'Assurance maladie est :', options:['Facultative, selon les revenus','Réservée aux citoyens français','Automatique seulement pour les salariés','Obligatoire pour tous les résidents de façon stable en France'], answer:3, explanation:'La Protection Universelle Maladie (PUMA) garantit à toute personne résidant en France de manière stable l\'accès à la Sécurité sociale.' },
  { id:'q238', level:['CR'], topic:5, q:'Qui peut demander un congé parental d\'éducation ?', options:['Uniquement la mère','Uniquement le père','Uniquement les parents d\'un premier enfant','Les deux parents salariés'], answer:3, explanation:'Le congé parental d\'éducation est ouvert aux deux parents salariés, après la naissance ou l\'adoption d\'un enfant.' },
  { id:'q239', level:['CR'], topic:5, q:'Quelle est la mission de France Travail ?', options:['Gérer les retraites des fonctionnaires','Former les enseignants','Contrôler les conditions de travail','Aider les demandeurs d\'emploi à trouver du travail et accompagner les entreprises qui recrutent'], answer:3, explanation:'France Travail (ex-Pôle Emploi) inscrit les demandeurs d\'emploi, verse les allocations chômage et accompagne la reprise d\'emploi.' },
  { id:'q240', level:['CR'], topic:5, q:'Quelles sont les affaires traitées par le conseil de prud\'hommes ?', options:['Les litiges locatifs','Les infractions pénales au travail','Les litiges entre l\'État et les fonctionnaires','Les conflits entre employeurs et salariés'], answer:3, explanation:'Le conseil de prud\'hommes est une juridiction paritaire qui règle les litiges entre salariés et employeurs du secteur privé.' },
  { id:'q241', level:['CR'], topic:5, q:'Dans une entreprise, le droit syndical permet :', options:['De refuser de travailler quand on le souhaite','D\'imposer des grèves illimitées','D\'exiger des augmentations sans négociation','De négocier collectivement les conditions de travail'], answer:3, explanation:'Le droit syndical permet aux salariés de se regrouper en syndicats pour défendre leurs intérêts et négocier avec les employeurs.' },
  { id:'q242', level:['CR'], topic:5, q:'Comment s\'appelle le diplôme passé par les élèves à la fin du collège ?', options:['Le baccalauréat','Le certificat d\'études primaires','Le CAP','Le brevet des collèges (DNB)'], answer:3, explanation:'Le Diplôme National du Brevet (DNB) est obtenu à la fin de la 3e (collège), généralement à 15 ans.' },
  { id:'q243', level:['CR'], topic:5, q:'À quel âge commence l\'instruction obligatoire des enfants ?', options:['5 ans','6 ans','7 ans','3 ans'], answer:3, explanation:'Depuis septembre 2019, l\'instruction obligatoire commence à 3 ans en France (abaissement de l\'ancien seuil de 6 ans).' },
  { id:'q244', level:['CR'], topic:5, q:'Quel est l\'âge de la majorité ?', options:['16 ans','17 ans','21 ans','18 ans'], answer:3, explanation:'La majorité légale est fixée à 18 ans en France depuis 1974. Elle confère la pleine capacité juridique.' },
  { id:'q245', level:['CR'], topic:5, q:'Dans une entreprise, le droit de grève autorise :', options:['De refuser tout travail de façon permanente','D\'occuper les locaux indéfiniment','De contraindre les autres à cesser le travail','De cesser collectivement le travail pour défendre des revendications professionnelles'], answer:3, explanation:'Le droit de grève est constitutionnel. Il permet d\'arrêter collectivement le travail, mais ne peut forcer personne à y participer.' },
  { id:'q246', level:['CR'], topic:5, q:'Qu\'est-ce que l\'école maternelle ?', options:['L\'école primaire pour enfants de 6 à 11 ans','Un établissement pour enfants de 0 à 3 ans','Un lycée professionnel pour jeunes mères','L\'école pour les enfants de 3 à 6 ans'], answer:3, explanation:'L\'école maternelle accueille les enfants de 3 à 6 ans. Elle est obligatoire depuis 2019 et constitue le premier cycle de l\'enseignement.' },
  { id:'q247', level:['CR'], topic:5, q:'Qu\'est-ce que le principe de confidentialité dans le domaine de la santé ?', options:['L\'obligation pour le médecin de tout dire à la famille','L\'obligation de consulter uniquement des médecins agréés','Le droit de refuser tout traitement','Le droit du patient à ce que ses informations médicales restent secrètes'], answer:3, explanation:'Le secret médical protège les informations de santé du patient. Le médecin ne peut les divulguer sans l\'accord du patient, sauf exceptions légales.' },
  { id:'q248', level:['CR'], topic:5, q:'Quelles sont les conditions pour toucher les allocations chômage ?', options:['Être de nationalité française','Ne jamais avoir travaillé','Avoir moins de 50 ans','Avoir travaillé suffisamment longtemps et être inscrit comme demandeur d\'emploi'], answer:3, explanation:'Pour bénéficier de l\'allocation chômage (ARE), il faut avoir cotisé suffisamment, être involontairement privé d\'emploi et être inscrit à France Travail.' },
  { id:'q249', level:['CR'], topic:5, q:'À l\'école, un enfant en situation de handicap :', options:['Est scolarisé uniquement en établissement spécialisé','Ne peut pas aller à l\'école publique','Doit être accompagné d\'un parent en permanence','A le droit d\'être scolarisé en milieu ordinaire avec les adaptations nécessaires'], answer:3, explanation:'La loi du 11 février 2005 garantit à tout enfant handicapé le droit à une scolarisation en milieu ordinaire, avec les aménagements nécessaires (AESH, PPS).' },
  { id:'q250', level:['CR'], topic:5, q:'Quelles sont les conditions pour qu\'un mariage soit reconnu juridiquement ?', options:['Une cérémonie religieuse suffit','Un contrat notarié suffit','L\'accord du préfet est nécessaire','Le mariage doit être célébré civilement à la mairie, avec consentement libre des deux époux majeurs'], answer:3, explanation:'Le mariage civil exige le consentement libre des deux époux, leur majorité (ou émancipation), et la célébration devant l\'officier d\'état civil.' }
];
